CREATE TABLE public.answer_state (response_id uuid DEFAULT gen_random_uuid(), attempt_id uuid, apprenant_id uuid, question_id text, valeur jsonb, revision integer DEFAULT 1, updated_at timestamp with time zone DEFAULT now(), updated_by uuid, session_origine text);
CREATE TABLE public.apprenants (id uuid DEFAULT gen_random_uuid(), nom text, prenom text, email text, telephone text, adresse text, code_postal text, ville text, date_naissance date, numero_dossier_cma text, statut text DEFAULT 'particulier'::text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), mode_financement text DEFAULT 'personnel'::text, civilite text, organisme_financeur text, type_apprenant text, formation_choisie text, montant_ttc numeric, date_debut_formation text, date_fin_formation text, creneau_horaire text, date_examen_theorique text, date_formation_catalogue text, montant_paye numeric DEFAULT 0, moyen_paiement text, notes text, date_paiement date, type_examen text, lieu_examen text, b2_vierge boolean DEFAULT false, resultat_examen text, inscrit_france_travail boolean DEFAULT false, date_examen_pratique text, documents_complets boolean DEFAULT false, heure_examen_pratique text, resultat_examen_pratique text, auth_user_id uuid, date_debut_cours_en_ligne date, date_fin_cours_en_ligne date, modules_autorises text[], mot_de_passe_cma text, deleted_at timestamp with time zone, societe_nom text, societe_siret text, societe_tva_intra text, societe_adresse text, societe_code_postal text, societe_ville text, facture_contact_nom text, facture_contact_email text, facture_contact_telephone text, responsable_contact_centre boolean DEFAULT false, relance_dossier_bienvenue_exclu boolean DEFAULT false, heures_elearning numeric, heures_presentiel numeric, heures_totales numeric, heures_pratique numeric, source_inscription text DEFAULT 'manuel'::text, mot_de_passe_plateforme text, emails_bloques boolean DEFAULT false, statut_suivi text, modalite_formation text, frais_examen text, abandonnee boolean DEFAULT false, date_abandon date, identifiant_cma text, compte_cours_archive_at timestamp with time zone, compte_cours_archive_par uuid, date_acceptation_cpf date);
CREATE TABLE public.audit_journal (event_id bigint, operation text, cible_type text, cible_id text, exam_id text, exam_version_id uuid, attempt_id uuid, apprenant_id uuid, auteur uuid, auteur_email text, avant jsonb, apres jsonb, origine text, session_technique text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.core_exam_results (result_id uuid DEFAULT gen_random_uuid(), attempt_id uuid, apprenant_id uuid, result_revision integer DEFAULT 1, status text DEFAULT 'provisoire'::text, score numeric, total numeric, qrc_restantes integer DEFAULT 0, published_at timestamp with time zone, updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.core_operations (operation_id uuid, operation_type text, apprenant_id uuid, attempt_id uuid, auteur uuid, cible jsonb DEFAULT '{}'::jsonb, resultat jsonb DEFAULT '{}'::jsonb, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.exam_attempts_v2 (attempt_id uuid DEFAULT gen_random_uuid(), apprenant_id uuid, exam_id text, exam_version_id uuid, snapshot jsonb, snapshot_fingerprint text, started_at timestamp with time zone DEFAULT now(), finished_at timestamp with time zone, etat text DEFAULT 'en_cours'::text, is_test boolean DEFAULT false);
CREATE TABLE public.qrc_correction_events (correction_event_id bigint, qrc_instance_id uuid, attempt_id uuid, question_id text, apprenant_id uuid, etat_precedent text, etat_nouveau text, note_precedente numeric, note_nouvelle numeric, commentaire text, corrige_par uuid, corrige_email text, operation_id uuid, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.qrc_instances_v2 (qrc_instance_id uuid DEFAULT gen_random_uuid(), attempt_id uuid, question_id text, apprenant_id uuid, reponse jsonb, etat text DEFAULT 'en_attente'::text, note numeric, corrige_par uuid, corrige_email text, corrige_at timestamp with time zone, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.user_roles (id uuid DEFAULT gen_random_uuid(), user_id uuid, role text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.qrc_verification_demandes (id uuid, qrc_instance_id uuid, attempt_id uuid, apprenant_id uuid, question_id text, statut text, note_ia numeric, note_finale numeric, traitee_par uuid, traitee_email text, traitee_at timestamp with time zone, created_at timestamp with time zone);
